SELECT "t3"."order_number", "t3"."invoice_id", "t3"."due", "t3"."open_amount", 'hold_ar' AS "route", 'overdue' AS "context"
FROM (SELECT "order_number", "invoice_id", "due", "amount" - "paid" AS "open_amount"
        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                        FROM "order"
                        WHERE "state" IN ('held', 'placed')) AS "t0"
                    INNER JOIN "invoice" ON "t0"."customer" = "invoice"."customer") AS "t1"
        WHERE "t1"."status" = 'open' AND "t1"."due" < :as_of) AS "t3"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t33"."order_number", "t33"."customer", "t33"."channel", "t33"."fulfilling_warehouse", "t33"."value", "t33"."placed_date", "t33"."state", COALESCE("t33"."n_short", 0) AS "n_short", COALESCE("t33"."n_price", 0) AS "n_price", COALESCE("t39"."n_due", 0) AS "n_due"
                FROM (SELECT "t21"."order_number", "t21"."customer", "t21"."channel", "t21"."fulfilling_warehouse", "t21"."value", "t21"."placed_date", "t21"."state", "t21"."n_short", "t32"."n_price"
                        FROM (SELECT "t5"."order_number", "t5"."customer", "t5"."channel", "t5"."fulfilling_warehouse", "t5"."value", "t5"."placed_date", "t5"."state", "t20"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t5"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t15"."order_number", "t15"."customer", "t15"."channel", "t15"."fulfilling_warehouse", "t15"."value", "t15"."placed_date", "t15"."state", "t15"."line_no", "t15"."item", "t15"."quantity", "t15"."unit_price", "t15"."ext_sales_price", "t15"."warehouse", "t15"."sold_date", "t15"."customer0", "t15"."channel0", "t15"."as_of_date", "t15"."quantity_on_hand", "t15"."_ttrp_g_n9_0", "t15"."_ttrp_g_n9_1", "t16"."warehouse" AS "warehouse0", "t16"."from_date", "t16"."to_date", "t16"."reason", COALESCE("t15"."quantity_on_hand", 0) AS "on_hand", "t16"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t9"."order_number", "t9"."customer", "t9"."channel", "t9"."fulfilling_warehouse", "t9"."value", "t9"."placed_date", "t9"."state", "t9"."line_no", "t9"."item", "t9"."quantity", "t9"."unit_price", "t9"."ext_sales_price", "t9"."warehouse", "t9"."sold_date", "t9"."customer0", "t9"."channel0", "t9"."as_of_date", "t9"."quantity_on_hand", "t9"."_ttrp_g_n9_0", "t9"."_ttrp_g_n9_1"
                                                        FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t8"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t8"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t8"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t8"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t7"
                                                                            INNER JOIN "sales_line" ON "t7"."order_number" = "sales_line"."order_number") AS "t8"
                                                                    LEFT JOIN "inventory" ON "t8"."item" = "inventory"."item" AND "t8"."warehouse" = "inventory"."warehouse") AS "t9"
                                                            INNER JOIN (SELECT CASE WHEN "t12"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t12"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t12"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t12"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                                                FROM (SELECT "t11"."order_number", "t11"."customer", "t11"."channel", "t11"."fulfilling_warehouse", "t11"."value", "t11"."placed_date", "t11"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t11"
                                                                            INNER JOIN "sales_line" AS "sales_line0" ON "t11"."order_number" = "sales_line0"."order_number") AS "t12"
                                                                    LEFT JOIN "inventory" AS "inventory0" ON "t12"."item" = "inventory0"."item" AND "t12"."warehouse" = "inventory0"."warehouse"
                                                                GROUP BY CASE WHEN "t12"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t12"."order_number" AS VARCHAR) END, CASE WHEN "t12"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t12"."line_no" AS VARCHAR) END) AS "t14" ON "t9"."_ttrp_g_n9_0" = "t14"."_ttrp_g_n9_0" AND "t9"."_ttrp_g_n9_1" = "t14"."_ttrp_g_n9_1" AND "t9"."as_of_date" = "t14"."_ttrp_latest_n9") AS "t15"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t16" ON "t15"."warehouse" = "t16"."warehouse") AS "t17"
                                        WHERE "t17"."outage" OR "t17"."on_hand" < "t17"."quantity"
                                        GROUP BY "order_number") AS "t20" ON "t5"."order_number" = "t20"."order_number") AS "t21"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t24"."order_number", "t24"."line_no", "t24"."item", "t24"."unit_price", "t24"."customer", "t24"."channel", "t24"."placed_date", "t28"."order_number" AS "order_number0", "t28"."line_no" AS "line_no0", "t28"."price"
                                        FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t23"."customer", "t23"."channel", "t23"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t23"
                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t23"."order_number" = "sales_line1"."order_number") AS "t24"
                                            INNER JOIN (SELECT "t27"."order_number", "t27"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t26"."customer", "t26"."channel", "t26"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t26"
                                                            INNER JOIN "sales_line" AS "sales_line2" ON "t26"."order_number" = "sales_line2"."order_number") AS "t27"
                                                    LEFT JOIN "customer_price" ON "t27"."item" = "customer_price"."item" AND "t27"."customer" = "customer_price"."customer" AND "t27"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t27"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t27"."item" = "price_list"."item" AND "t27"."channel" = "price_list"."channel" AND "t27"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t27"."placed_date" <= "price_list"."valid_to")) AS "t28" ON "t24"."order_number" = "t28"."order_number" AND "t24"."line_no" = "t28"."line_no") AS "t29"
                                WHERE "t29"."price" IS NULL OR ABS("t29"."unit_price" - "t29"."price") > :tolerance
                                GROUP BY "order_number0") AS "t32" ON "t21"."order_number" = "t32"."order_number") AS "t33"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t35"."order_number", "t35"."customer", "t35"."channel", "t35"."fulfilling_warehouse", "t35"."value", "t35"."placed_date", "t35"."state", "invoice0"."invoice_id", "invoice0"."order_number" AS "order_number0", "invoice0"."issued", "invoice0"."due", "invoice0"."amount", "invoice0"."paid", "invoice0"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t35"
                                    INNER JOIN "invoice" AS "invoice0" ON "t35"."customer" = "invoice0"."customer") AS "t36"
                        WHERE "t36"."status" = 'open' AND "t36"."due" < :as_of
                        GROUP BY "order_number") AS "t39" ON "t33"."order_number" = "t39"."order_number") AS "t40"
        WHERE "t40"."n_due" > 0
        GROUP BY "order_number") AS "t43" ON "t3"."order_number" = "t43"."order_number"
